item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA items 14 and 16 distinguish evidence of repeated testing from evidence about score variation. Neither is established here."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "Without repeated runs, stability remains unknown; this does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA item 14 would be No because non-repetition is explicit. Items 14 and 16 provide no basis for concluding that scores are stable."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same stated conditions occurred."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "MESA item 14 is satisfied. The reported variation supports stability under the stated criterion for these runs and conditions, without establishing stability in other settings."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly reports repeated testing under the same conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA item 14 is satisfied because testing occurred, despite unfavourable results. The variation undermines stable-score interpretations under the report's criterion."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation supplies no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions do not establish score stability."
        }
      ],
      "instrument_review": "Installation instructions are relevant to MESA item 22 on reproducibility, but they do not resolve items 14 and 16 concerning repeated runs and score variation."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "Under MESA items 9, 20 and 25, the evidence supports the narrow intended comparison. Cross-domain conclusions lack supporting coverage or findings."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of greater general intelligence."
        }
      ],
      "instrument_review": "MESA items 9, 20 and 25 expose a mismatch between narrow grid evidence and the intended cross-domain selection. Stating that intended use does not validate it."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supplied no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks and reported difference interval support better correctness with A in the studied workshop."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "For MESA items 16, 20 and 25, the later trial adds evidence linking assistance to decision correctness, with reported uncertainty. Support is limited to the studied workshop and conditions; safety improvement remains unestablished."
    }
  ],
  "closing_note": "No instructions were unclear. Probe labels classify evidential support, not MESA ratings; missing evidence was not treated as contradiction."
}
